<script setup lang="ts">
import {ArrowDown,ArrowUp,Plus,Trash2} from '@lucide/vue'
import {routeModes,routeShapes,difficulties,type SavedRouteInput} from './library'
const props=defineProps<{value:SavedRouteInput}>()
function move(index:number,delta:number){const list=props.value.waypoints,next=index+delta;if(next<0||next>=list.length)return;const item=list.splice(index,1)[0]!;list.splice(next,0,item)}
function number(event:Event,key:'distanceKm'|'durationMinutes'|'ascentM'){const input=event.target as HTMLInputElement;props.value[key]=input.value===''?null:input.valueAsNumber}
function tags(event:Event){props.value.tags=[...new Set((event.target as HTMLInputElement).value.split(/[,，、]/).map(s=>s.trim().slice(0,40)).filter(Boolean))].slice(0,12)}
</script>
<template>
  <div class="tw-form-grid"><label class="tw-field">路线名称<input v-model="value.name" required maxlength="180" placeholder="例如：湖畔环湖骑行"/></label><label class="tw-field">所在城市 / 地区<input v-model="value.city" required maxlength="120" placeholder="例如：杭州"/></label></div>
  <div class="tw-route-form-triple"><label class="tw-field">出行方式<select v-model="value.mode"><option v-for="(label,key) in routeModes" :key="key" :value="key">{{ label }}</option></select></label><label class="tw-field">路线形态<select v-model="value.shape"><option v-for="(label,key) in routeShapes" :key="key" :value="key">{{ label }}</option></select></label><label class="tw-field">难度<select v-model="value.difficulty"><option v-for="(label,key) in difficulties" :key="key" :value="key">{{ label }}</option></select></label></div>
  <div class="tw-route-form-triple"><label class="tw-field">里程 · km<input :value="value.distanceKm??''" type="number" min="0.01" max="10000" step="0.01" placeholder="未知留空" @input="number($event,'distanceKm')"/></label><label class="tw-field">耗时 · 分钟<input :value="value.durationMinutes??''" type="number" min="1" max="43200" step="1" placeholder="未知留空" @input="number($event,'durationMinutes')"/></label><label class="tw-field">累计爬升 · m<input :value="value.ascentM??''" type="number" min="0" max="20000" step="1" placeholder="未知留空" @input="number($event,'ascentM')"/></label></div>
  <section class="tw-waypoint-editor"><header><div><h3>沿途的每一站</h3><p>按实际行进顺序排列；点位名称不会自动变成地图坐标。</p></div><button class="tw-button secondary" type="button" :disabled="value.waypoints.length>=80" @click="value.waypoints.push({name:'',note:''})"><Plus :size="14"/>加一站</button></header><article v-for="(point,index) in value.waypoints" :key="index"><span>{{ index+1 }}</span><div><input v-model="point.name" required maxlength="180" :aria-label="'第'+(index+1)+'站名称'" placeholder="途经点名称"/><input v-model="point.note" maxlength="300" :aria-label="'第'+(index+1)+'站备注'" placeholder="路段、补水点或到达方式（选填）"/></div><div class="tw-waypoint-tools"><button class="tw-icon" type="button" :disabled="index===0" aria-label="上移途经点" @click="move(index,-1)"><ArrowUp :size="15"/></button><button class="tw-icon" type="button" :disabled="index===value.waypoints.length-1" aria-label="下移途经点" @click="move(index,1)"><ArrowDown :size="15"/></button><button class="tw-icon danger" type="button" :disabled="value.waypoints.length<=2" aria-label="移除途经点" @click="value.waypoints.splice(index,1)"><Trash2 :size="15"/></button></div></article></section>
  <label class="tw-field">标签<input :value="value.tags.join('，')" maxlength="490" placeholder="经典路线，入门，秋季（逗号分隔，最多 12 个）" @change="tags"/></label><label class="tw-field">路线介绍<textarea v-model="value.description" rows="3" maxlength="5000" placeholder="路线亮点、路面和适合的季节…"></textarea></label><label class="tw-field">出行提示<textarea v-model="value.tips" rows="2" maxlength="3000" placeholder="交通接驳、装备、补给或需要核对的事项…"></textarea></label><label class="tw-field">来源链接<input v-model="value.sourceUrl" type="url" maxlength="1500" placeholder="https://…（选填）"/></label>
  <details v-if="value.evidence||value.sourceLabel" class="tw-material-evidence"><summary>查看资料来源 · {{ value.sourceLabel }}</summary><blockquote v-if="value.evidence">{{ value.evidence }}</blockquote><p v-else>没有可核对的原文片段，请自行确认路线信息。</p></details>
</template>
